package com.jnapanam.sportszone.training.dto;import com.jnapanam.sportszone.training.model.TrainingProgram;import java.util.UUID;public record ProgramResponse(UUID id,String code,String sportCode,String name,String description,Integer minAge,Integer maxAge,String level,String status){public static ProgramResponse from(TrainingProgram p){return new ProgramResponse(p.getId(),p.getCode(),p.getSport().getCode(),p.getName(),p.getDescription(),p.getMinAge(),p.getMaxAge(),p.getLevel().name(),p.getStatus().name());}}
